// Purpose: Verify Archive and Execution Context. Keep this deterministic and fail closed.
const r = $json;
const historicalImport = r.historical_import;
if (historicalImport !== undefined && typeof historicalImport !== 'boolean') {
    throw new Error('historical_import must be boolean');
}
if (historicalImport === true && (r.source_code !== 'ADCB_CASHBACK'
    || !r.historical_account_id
    || !r.account_id
    || String(r.historical_account_id) !== String(r.account_id))) {
    throw new Error('ADCB historical import requires the configured account binding');
}
const sourceAttachmentId = String(r.source_attachment_id || r.attachment_id || '').trim();
const attachmentId = String(r.attachment_id || r.source_attachment_id || '').trim();
if (r.source_attachment_id && r.attachment_id && sourceAttachmentId !== attachmentId) {
    throw new Error('ATTACHMENT_ID_ALIAS_MISMATCH');
}
for (const k of ['run_id', 'source_code', 'message_id', 'document_sha256', 'onedrive_item_id', 'manifest_onedrive_parent_id', 'config_version', 'actual_file_id', 'account_id', 'card_code', 'period_key']) {
    if (!r[k])
        throw new Error(`Missing trusted immutable field ${k}`);
}
if (!attachmentId)
    throw new Error('Missing trusted immutable field attachment_id');
if (typeof r.cashback_close_required !== 'boolean') {
    throw new Error('Missing trusted immutable field cashback_close_required');
}
if (!['SCHEDULE', 'SUBWORKFLOW', 'REPLAY'].includes(r.trigger_kind)) {
    throw new Error('Manual and MCP mutation are forbidden');
}
return [{
        json: {
            run_id: r.run_id,
            source_code: r.source_code,
            message_id: r.message_id,
            document_sha256: r.document_sha256,
            onedrive_item_id: r.onedrive_item_id,
            manifest_onedrive_parent_id: r.manifest_onedrive_parent_id,
            config_version: r.config_version,
            actual_file_id: r.actual_file_id,
            account_id: r.account_id,
            card_code: r.card_code,
            cashback_close_required: r.cashback_close_required,
            period_key: r.period_key,
            trigger_kind: r.trigger_kind,
            attachment_id: attachmentId,
            source_attachment_id: sourceAttachmentId,
            pipeline_contract: r.pipeline_contract,
            actual_writer_workflow: r.actual_writer_workflow,
            source_mutation_forbidden: r.source_mutation_forbidden,
            historical_import: historicalImport === true,
            historical_source: historicalImport === true ? 'ADCB_CASHBACK' : undefined,
            historical_account_id: historicalImport === true ? String(r.historical_account_id) : undefined,
        },
        binary: $binary,
    }];

// Purpose: Build Bounded AI Policy Requests. Keep this deterministic and fail closed.
const requests = $json.ai_requests;
if (!Array.isArray(requests) || !requests.length || requests.length > 20)
    throw new Error('INVALID_AI_REQUEST_BATCH');
return requests.map(r => {
    if (!r.policy_id || !Array.isArray(r.unresolved) || !r.unresolved.length)
        throw new Error('INVALID_AI_POLICY_REQUEST');
    return { json: { policy_id: String(r.policy_id), unresolved: r.unresolved.map(x => ({ transaction_id: x.transaction_id, allowed_fields: x.allowed_fields, redacted_context: x.redacted_context || {} })) } };
});

// Purpose: Merge Allowed AI Proposals. Keep this deterministic and fail closed.
const base = $('Apply N8N Only Rules').first().json;
const proposals = $input.all().flatMap(item => (Array.isArray(item.json.proposals) ? item.json.proposals : []));
const locked = new Set([
    'amount', 'date', 'source_id', 'imported_id', 'direction', 'topic',
    'dedupe_key', 'reconciliation_state', 'cashback', 'cashback_amount',
]);
const pairs = new Set();
for (const proposal of proposals) {
    const pair = JSON.stringify([
        String(proposal.transaction_id),
        String(proposal.field),
    ]);
    if (locked.has(String(proposal.field)) || pairs.has(pair)) {
        throw new Error('AI_LOCKED_OR_DUPLICATE_FIELD_REJECTED');
    }
    pairs.add(pair);
}
return [{ json: { ...base, accepted_ai_proposals: proposals } }];

// Purpose: Validate Statement Reconciliation and IDs. Keep this deterministic and fail closed.
const r = $json;
if (r.document_profile === 'BROWSER_CAPTURE_V1' && r.adapter === 'browser_capture_v1_snapshot') {
    return [{ json: { ...r, browser_match_status: 'MATCHED_REVIEW_ONLY', actual_mutation: false, cashback_mutation: false } }];
}
if (!Array.isArray(r.transactions) || !r.transactions.length)
    throw new Error('EMPTY_STATEMENT');
const ids = r.transactions.map(t => t.transaction_id);
if (ids.some(x => !x) || new Set(ids).size !== ids.length)
    throw new Error('INVALID_OR_DUPLICATE_SOURCE_TRANSACTION_ID');
if (r.reconciliation?.balanced !== true)
    throw new Error('STATEMENT_RECONCILIATION_FAILED');
return [{ json: r }];

// Purpose: Build Canonical Delta Artifact. Keep this deterministic and fail closed.
const r = $json, s = $('Verify Archive and Execution Context').first().json;
if (!Array.isArray(r.actual_transactions) || !r.actual_transactions.length)
    throw new Error('EMPTY_ACTUAL_PROJECTION');
const manifest = {
    schema_version: 'actual-delta-v1',
    source_code: s.source_code,
    document_sha256: s.document_sha256,
    config_version: s.config_version,
    parser_version: r.parser_version || 'n8n-nodes-finance@0.1.0',
    actual_file_id: s.actual_file_id,
    account_id: s.account_id,
    card_code: s.card_code,
    historical_import: s.historical_import === true,
    ...(s.historical_import === true
        ? { historical_source: s.historical_source, historical_account_id: s.historical_account_id }
        : {}),
    period_start: r.period_start,
    period_end: r.period_end,
    expected_statement_balance_minor: r.reconciliation?.ending_balance_minor,
    transactions: r.actual_transactions,
};
return [{ json: { manifest, file_name: `${s.document_sha256}.actual-delta-v1.json` } }];

// Purpose: Verify Durable Canonical Delta. Keep this deterministic and fail closed.
const expected = $('SHA-256 Canonical Delta').first().json.canonical_delta_sha256, observed = $json.readback_sha256, upload = $('Archive Canonical Delta in OneDrive').first().json;
if (!expected || expected !== observed || !upload.id)
    throw new Error('CANONICAL_DELTA_ARCHIVE_READBACK_FAILED');
return [{ json: { delta_artifact_item_id: String(upload.id), delta_artifact_etag: String(upload.eTag || upload.etag || ''), artifact_sha256: expected, delta_schema_version: 'actual-delta-v1' } }];

// Purpose: Validate Reconciliation Readback. Keep this deterministic and fail closed.
const row = $json || {};
const source = $('Verify Archive and Execution Context').first().json;
const actual = $('Apply Prepared Outbox Safely').first().json;
const request = $('Build Cashback Reconciliation Request').first().json.cashback_reconcile;
const text = value => String(value ?? '').trim();
let closeId = '';
try {
    closeId = text($('Validate Cashback Finalization Response').first().json.close_id);
}
catch (_) {
    closeId = '';
}
if (text(row.source_code) !== text(source.source_code)
    || text(row.period_key) !== text(source.period_key)
    || Number(row.reconciliation_version) !== 1
    || row.state !== 'COMMITTED'
    || text(row.statement_sha256).toLowerCase() !== text(request.statement_sha256).toLowerCase()
    || text(row.actual_verification_sha256).toLowerCase() !== text(actual.observed_payload_sha256).toLowerCase())
    throw new Error('RECONCILIATION_READBACK_BINDING_MISMATCH');
if (source.cashback_close_required === true && (!closeId || text(row.cashback_close_id) !== closeId))
    throw new Error('RECONCILIATION_READBACK_CLOSE_MISMATCH');
if (source.cashback_close_required !== true && text(row.cashback_close_id))
    throw new Error('RECONCILIATION_READBACK_UNEXPECTED_CLOSE');
return [{ json: { ...row, reconciliation_readback_verified: true } }];

// Purpose: Select Existing Outbox Or Prepare. Keep this deterministic and fail closed.
const draft = $('Prepare Outbox Intent').first().json;
const existing = $json || {};
const state = String(existing.state || '').trim().toUpperCase();
const states = new Set(['PREPARED', 'ACTUAL_OBSERVED', 'VERIFIED', 'COMMITTED']);
if (!state)
    return [{ json: { ...draft, existing_outbox_replay: false } }];
if (!states.has(state))
    throw new Error('ACTUAL_OUTBOX_STATE_INVALID');
const exact = ['idempotency_key', 'actual_file_id', 'account_id', 'card_code', 'delta_sha256'];
for (const field of exact) {
    if (String(existing[field] ?? '').trim() !== String(draft[field] ?? '').trim())
        throw new Error('ACTUAL_OUTBOX_IDENTITY_MISMATCH:' + field);
}
return [{ json: { ...draft, ...existing, existing_outbox_replay: true } }];

// Purpose: Compare Terminal Receipt Readback. Keep this deterministic and fail closed.
const expected = $('Upsert Terminal Pipeline Receipt').first().json, observed = $json;
if (observed.run_id !== expected.run_id || observed.workflow_code !== 'SHARED_STATEMENT_PIPELINE' || observed.state !== 'SUCCEEDED' || observed.receipt_sha256 !== expected.receipt_sha256)
    throw new Error('TERMINAL_RECEIPT_READBACK_MISMATCH');
return [{ json: observed }];

// Purpose: Build Trusted Cashback Finalization. Keep this deterministic and fail closed.
const source = $('Verify Archive and Execution Context').first().json;
const statement = $('Validate Statement Reconciliation and IDs').first().json;
const manifest = $('Build Canonical Delta Artifact').first().json.manifest;
const actual = $json;
const text = value => String(value ?? '').trim();
const required = ['batch_id', 'actual_file_id', 'account_id', 'card_code', 'state', 'verification_version', 'period_start', 'period_end', 'expected_payload_sha256', 'observed_payload_sha256', 'invariants_passed', 'verified_at'];
for (const field of required) {
    if (actual[field] === undefined || actual[field] === null || actual[field] === '')
        throw new Error(`ACTUAL_CLOSE_RECEIPT_MISSING:${field}`);
}
if (actual.state !== 'COMMITTED' || actual.writer_release_verified !== true)
    throw new Error('ACTUAL_CLOSE_RECEIPT_STALE');
if (text(actual.actual_file_id) !== text(source.actual_file_id) || text(actual.account_id).toUpperCase() !== text(source.account_id).toUpperCase())
    throw new Error('ACTUAL_CLOSE_RECEIPT_ACCOUNT_MISMATCH');
const cardCode = text(source.card_code);
if (!cardCode || !text(actual.card_code) || text(actual.card_code).toUpperCase() !== cardCode.toUpperCase())
    throw new Error('ACTUAL_CLOSE_RECEIPT_CARD_MISMATCH');
if (text(actual.period_start) !== text(manifest.period_start) || text(actual.period_end) !== text(manifest.period_end))
    throw new Error('ACTUAL_CLOSE_RECEIPT_PERIOD_MISMATCH');
if (!/^[a-f0-9]{64}$/i.test(text(actual.expected_payload_sha256)) || !/^[a-f0-9]{64}$/i.test(text(actual.observed_payload_sha256)) || text(actual.expected_payload_sha256).toLowerCase() !== text(actual.observed_payload_sha256).toLowerCase())
    throw new Error('ACTUAL_CLOSE_RECEIPT_DIGEST_MISMATCH');
if (actual.invariants_passed !== true)
    throw new Error('ACTUAL_CLOSE_RECEIPT_INVARIANTS_FAILED');
const receipt = {
    account_id: text(actual.account_id),
    actual_file_id: text(actual.actual_file_id),
    card_code: cardCode,
    expected_account_balance: actual.expected_account_balance ?? null,
    expected_amount_sum_minor: actual.expected_amount_sum_minor ?? null,
    expected_count: actual.expected_count ?? null,
    expected_payload_sha256: text(actual.expected_payload_sha256).toLowerCase(),
    invariants_passed: true,
    observed_account_balance: actual.observed_account_balance ?? null,
    observed_amount_sum_minor: actual.observed_amount_sum_minor ?? null,
    observed_count: actual.observed_count ?? null,
    observed_payload_sha256: text(actual.observed_payload_sha256).toLowerCase(),
    batch_id: text(actual.batch_id),
    period_end: text(actual.period_end),
    period_start: text(actual.period_start),
    state: 'COMMITTED',
    verification_version: Number(actual.verification_version),
    verified_at: text(actual.verified_at),
    writer_release_verified: true,
};
// The native Convert to File and Crypto nodes below calculate this digest. The draft never authenticates itself.
const actual_import_receipt_sha256 = undefined;
const statement_sha256 = text(statement.statement_sha256 || statement.document_sha256 || source.document_sha256);
if (!/^[a-f0-9]{64}$/i.test(statement_sha256))
    throw new Error('CASHBACK_CLOSE_STATEMENT_DIGEST_INVALID');
const statement_reference = text(statement.statement_reference || source.statement_reference) || `statement:${source.source_code}:${source.document_sha256}`;
const statement_evidence_reference = text(statement.statement_evidence_reference || source.statement_evidence_reference) || `onedrive:${source.onedrive_item_id}:${source.document_sha256}`;
const statement_document_url = text(statement.statement_document_url || source.statement_document_url) || `onedrive-item:${source.onedrive_item_id}`;
const cashback_finalization = { statement_reference, statement_sha256, statement_evidence_reference, statement_document_url, actual_import_receipt: receipt, actual_import_receipt_sha256 };
return [{ json: { ...actual, cashback_finalization, actual_import_receipt: receipt, actual_import_receipt_sha256 } }];

// Purpose: Finalize Trusted Cashback Payload. Keep this deterministic and fail closed.
const draft = $('Build Trusted Cashback Finalization').first().json;
const digest = String($json.actual_import_receipt_sha256 || '').toLowerCase();
if (!/^[a-f0-9]{64}$/.test(digest))
    throw new Error('ACTUAL_CLOSE_RECEIPT_DIGEST_MISSING');
const cashback_finalization = { ...draft.cashback_finalization, actual_import_receipt_sha256: digest };
return [{ json: { ...draft, actual_import_receipt_sha256: digest, cashback_finalization } }];

// Purpose: Build Cashback Reconciliation Request. Keep this deterministic and fail closed.
const draft = $json;
const statement = $('Validate Statement Reconciliation and IDs').first().json;
const source = $('Verify Archive and Execution Context').first().json;
const manifest = $('Build Canonical Delta Artifact').first().json.manifest;
const allowed = new Set(['PURCHASE', 'REFUND', 'REVERSAL']);
const rows = Array.isArray(statement.transactions) ? statement.transactions : [];
const transactions = rows.filter(row => allowed.has(String(row.transaction_type || row.event_type || '').toUpperCase())).map(row => {
    const eventType = String(row.event_type || row.transaction_type || '').trim().toUpperCase();
    const purchaseType = String(row.purchase_type || row.category || 'GENERAL').trim().toUpperCase();
    const transactionId = String(row.transaction_id || row.statement_transaction_id || '').trim();
    if (!transactionId || (!row.transaction_date && !row.occurred_at) || (row.amount_aed === undefined && row.amount === undefined))
        throw new Error('CASHBACK_RECONCILE_ROW_INVALID');
    return {
        statement_transaction_id: transactionId,
        occurred_at: String(row.occurred_at || String(row.transaction_date) + 'T00:00:00+04:00'),
        amount_aed: String(row.amount_aed ?? row.amount),
        currency: String(row.currency_original || row.currency || 'AED'),
        merchant: String(row.description || row.merchant || '').trim(),
        purchase_type: purchaseType,
        event_type: eventType,
    };
});
if (!transactions.length)
    throw new Error('CASHBACK_RECONCILE_EMPTY');
const cardCode = String(source.card_code || '').trim().toUpperCase();
if (!cardCode)
    throw new Error('CASHBACK_RECONCILE_CARD_MISSING');
const cashback_reconcile = {
    statement_reference: String(draft.cashback_finalization.statement_reference),
    statement_sha256: String(draft.cashback_finalization.statement_sha256),
    card_code: cardCode,
    period_start: String(manifest.period_start),
    period_end: String(manifest.period_end),
    transactions,
};
return [{ json: { ...draft, cashback_reconcile } }];

// Purpose: Validate Cashback Finalization Response. Keep this deterministic and fail closed.
const response = $json;
const period = response?.period;
const request = $('Build Cashback Reconciliation Request').first().json.cashback_reconcile;
const finalization = $('Finalize Trusted Cashback Payload').first().json.cashback_finalization;
if (!period || typeof period !== 'object' || Array.isArray(period))
    throw new Error('CASHBACK_FINALIZE_RESPONSE_PERIOD_MISSING');
const required = ['close_id', 'card_code', 'period_start', 'period_end', 'statement_reference', 'statement_sha256', 'actual_import_receipt_sha256', 'actual_verification_sha256', 'status', 'idempotent_replay'];
for (const field of required) {
    if (period[field] === undefined || period[field] === null || period[field] === '')
        throw new Error('CASHBACK_FINALIZE_RESPONSE_FIELD_MISSING:' + field);
}
if (period.status !== 'FINALIZED' || typeof period.idempotent_replay !== 'boolean')
    throw new Error('CASHBACK_FINALIZE_RESPONSE_STATUS_INVALID');
if (String(period.close_id).trim() === '')
    throw new Error('CASHBACK_FINALIZE_RESPONSE_CLOSE_ID_INVALID');
if (String(period.card_code).toUpperCase() !== String(request.card_code).toUpperCase()
    || String(period.period_start) !== String(request.period_start)
    || String(period.period_end) !== String(request.period_end)
    || String(period.statement_reference) !== String(request.statement_reference)
    || String(period.statement_sha256).toLowerCase() !== String(request.statement_sha256).toLowerCase()
    || String(period.actual_import_receipt_sha256).toLowerCase() !== String(finalization.actual_import_receipt_sha256).toLowerCase()
    || String(period.actual_verification_sha256).toLowerCase() !== String(finalization.actual_import_receipt_sha256).toLowerCase())
    throw new Error('CASHBACK_FINALIZE_RESPONSE_BINDING_MISMATCH');
return [{ json: { close_id: String(period.close_id), finalize_response: response } }];

// Purpose: Parse Browser Capture Adapter. Keep this deterministic and fail closed.
const input = $json;
const capture = input.browser_capture;
if (!capture || capture.schema_version !== 1 || !capture.source?.provider || !capture.account?.label) {
    throw new Error('BROWSER_CAPTURE_ADAPTER_CONTEXT_MISSING');
}
if (!['ACCOUNT_SNAPSHOT', 'STATEMENT_ROWS', 'TRANSACTION_ROWS', 'STATEMENT_PDF'].includes(String(capture.artifact?.kind || ''))) {
    throw new Error('BROWSER_CAPTURE_ADAPTER_KIND_INVALID');
}
if (capture.artifact.kind === 'STATEMENT_PDF') {
    throw new Error('BROWSER_CAPTURE_PDF_MUST_USE_PDF_PIPELINE');
}
if (capture.artifact.kind === 'ACCOUNT_SNAPSHOT') {
    return [{ json: {
                ...input,
                adapter: 'browser_capture_v1_snapshot',
                transactions: [],
                period_start: capture.source.date_range?.start || null,
                period_end: capture.source.date_range?.end || null,
                reconciliation: { balanced: true, browser_capture: true, balance_tied: false },
                browser_match_status: 'SNAPSHOT_REVIEW_ONLY',
                browser_retry: { attempt: 0, max_attempts: 3, exhausted: true },
                actual_mutation: false,
                cashback_mutation: false,
            } }];
}
const rows = capture.rows;
if (!Array.isArray(rows) || rows.length === 0 || rows.length > 10000) {
    throw new Error('BROWSER_CAPTURE_ROWS_INVALID');
}
const ids = new Set();
const transactions = rows.map((row, index) => {
    const transactionDate = String(row.transaction_date || '');
    const description = String(row.description || '').trim();
    const amount = String(row.amount_aed || '').trim();
    const direction = String(row.direction || '').toUpperCase();
    const sourceId = String(row.source_id || row.reference || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(transactionDate) || !description || !amount || !/^\d+(?:\.\d{1,2})?$/.test(amount) || direction === '') {
        throw new Error(`BROWSER_CAPTURE_ROW_INVALID:${index}`);
    }
    if (!['DEBIT', 'CREDIT'].includes(direction)) {
        throw new Error(`BROWSER_CAPTURE_DIRECTION_INVALID:${index}`);
    }
    if (sourceId) {
        if (ids.has(sourceId))
            throw new Error(`BROWSER_CAPTURE_DUPLICATE_SOURCE_ID:${sourceId}`);
        ids.add(sourceId);
    }
    const transactionId = `browser:${capture.capture_id}:${sourceId || index}`;
    return {
        transaction_id: transactionId,
        transaction_date: transactionDate,
        post_date: row.post_date || null,
        card_last4: row.account_last4 || capture.account.account_last4 || null,
        description,
        amount_aed: amount,
        signed_amount_aed: direction === 'CREDIT' ? `-${amount}` : amount,
        direction,
        source_direction: direction,
        transaction_type: row.transaction_type || undefined,
        amount_original: row.amount_original ?? null,
        currency_original: row.currency || capture.account.currency || 'AED',
        exchange_rate: null,
        source_line: index + 1,
        review_required: row.review_required === true || capture.source.capture_method === 'VISIBLE_ROWS',
        source_id: sourceId || null,
        source_type: 'browser_capture',
        browser_provider: capture.source.provider,
        browser_account_label: capture.account.label,
    };
});
return [{ json: {
            ...input,
            adapter: 'browser_capture_v1',
            transactions,
            period_start: capture.source.date_range?.start || null,
            period_end: capture.source.date_range?.end || null,
            reconciliation: { balanced: true, browser_capture: true, balance_tied: false },
            browser_match_status: 'READY_FOR_MATCH',
            browser_retry: { attempt: 0, max_attempts: 3, exhausted: false },
            actual_mutation: false,
            cashback_mutation: false,
        } }];

// Purpose: Match Browser Capture Rows and Bound Retry. Keep this deterministic and fail closed.
const input = $json;
if (!String(input.adapter || '').startsWith('browser_capture_v1'))
    return [{ json: input }];
const rows = Array.isArray(input.transactions) ? input.transactions : [];
if (input.adapter === 'browser_capture_v1_snapshot') {
    return [{ json: { ...input, browser_match_status: 'SNAPSHOT_REVIEW_ONLY' } }];
}
const ids = rows.map(row => String(row.transaction_id || ''));
if (!rows.length || ids.some(id => !id) || new Set(ids).size !== ids.length) {
    throw new Error('BROWSER_CAPTURE_MATCH_IDS_INVALID');
}
const retry = input.browser_retry || { attempt: 0, max_attempts: 3, exhausted: false };
if (Number(retry.attempt) > Number(retry.max_attempts)) {
    throw new Error('BROWSER_CAPTURE_RETRY_EXHAUSTED');
}
return [{ json: { ...input, browser_match_status: 'MATCHED_REVIEW_ONLY', browser_retry: { ...retry, exhausted: true } } }];

// Purpose: Complete Browser Capture Headless Receipt. Keep this deterministic and fail closed.
const input = $json;
if (!String(input.adapter || '').startsWith('browser_capture_v1') || input.actual_mutation !== false || input.cashback_mutation !== false) {
    throw new Error('BROWSER_CAPTURE_WRITE_BOUNDARY_FAILED');
}
return [{ json: { ...input, browser_handoff_status: 'STAGED_REVIEW_REQUIRED', actual_mutation: false, cashback_mutation: false, direct_actual_writer: false, direct_cashback_writer: false } }];
